  Definition MFRAME (mm : mem) (j8 : list byte) (s7v s6v s5v s4v : word) : Prop :=
    rw_cells psegs mm (usp0 + -128)
      [CB 8 j8; C8 s7v; C8 s6v; C8 s5v; C8 s4v; C8 (Z_to_bv 64 (envp_addr sp0 argv)); C8 (Z_to_bv 64 PMAIN);
       C8 (Z_to_bv 64 (argc argv)); C8 (Z_to_bv 64 (usp0 + 8)); C8 (Z_to_bv 64 PSTAGE2_RET)].

  Definition RSTAT (mm : mem) : Prop :=
    rw_cells psegs mm 0x37768 [C8 (Z_to_bv 64 0x37768); C8 (Z_to_bv 64 0x37768); C8 (Z_to_bv 64 0x37768); C8 (Z_to_bv 64 0); C4 (Z_to_bv 64 TID)]
    /\ rw_cells psegs mm 0x57a98 [C4 (Z_to_bv 64 0)]
    /\ rw_cells psegs mm 0x264b8 [C8 (Z_to_bv 64 0x26420); C8 (Z_to_bv 64 0x26418)]
    /\ rw_cells psegs mm 0x26418 [C8 (Z_to_bv 64 0x12ca0)]
    /\ rw_cells psegs mm 0x27728 [C1 (Z_to_bv 8 0)]
    /\ rw_cells psegs mm 0x26460 [C8 (Z_to_bv 64 0x1d794); C8 (Z_to_bv 64 0)]
