    /\ rw_cells psegs mm 0x26470 [C8 (Z_to_bv 64 0x26420)]
    /\ rw_cells psegs mm 0x26420 [C8 (Z_to_bv 64 0x274f0)]
    (* [comment removed for export] *)
    /\ rw_cells psegs mm 0x274c8 [C8 (Z_to_bv 64 0x274c8)]
    /\ (exists reg : bool, atx_state reg mm).

  (* [comment removed for export] *)
  Definition RSTATX (mm : mem) : Prop := exists reg : bool, atx_state reg mm.

  Definition rstat_addr (a : Z) : Prop :=
    (0x37768 <= a < 0x3778c) \/ (0x57a98 <= a < 0x57aa0) \/ (0x264b8 <= a < 0x264c8) \/ (0x26418 <= a < 0x26420)
    \/ (0x27728 <= a < 0x27729) \/ (0x26460 <= a < 0x26470) \/ (0x57ee0 <= a < 0x57ee8) \/ (0x57ef0 <= a < 0x57ef8)
    \/ (0x276c8 <= a < 0x276d0) \/ (0x275d8 <= a < 0x275e0) \/ (0x26470 <= a < 0x26478) \/ (0x26420 <= a < 0x26428)
    \/ (0x274c8 <= a < 0x274d0)
    \/ (0x57878 <= a < 0x57879) \/ (0x5787c <= a < 0x57884) \/ (0x57888 <= a < 0x578a0) \/ (0x57998 <= a < 0x579a0) \/ (0x37734 <= a < 0x37735).

  Lemma atx_state_addr_rstat : forall a, atx_state_addr a -> rstat_addr a.
